def segs(g,colors):
    H,W=len(g),len(g[0]); seen=set(); out=[]
    for r in range(H):
        for c in range(W):
            if g[r][c]!=0 and (r,c) not in seen:
                # vertical
                rr=r
                while rr<H and g[rr][c]==g[r][c]: rr+=1
                if rr-r>1: out.append(('v',g[r][c],c,r,rr-1)); seen.update([(i,j) for i in range(r,rr) for j in [c]])
                else:
                    cc=c
